template<class T>
struct Box
{
  struct Guard
  {
    Guard(Box & owner)
      : ref(owner)
    {
    }

    void operator()()
    {
      ref.value += 1;
    }

    Box & ref;
  };

  Box()
    : value(0)
  {
  }

  ~Box()
  {
    Guard(*this)();
  }

  int value;
};

struct Maker
{
  int one()
  {
    struct Piece
    {
      int value;
    };
    Box<Piece> box;
    return box.value;
  }

  int two()
  {
    struct Piece
    {
      int value;
    };
    Box<Piece> box;
    return box.value;
  }
};

int main()
{
  Maker maker;
  return maker.one() == 0 && maker.two() == 0 ? 0 : 1;
}

struct Value
{
  static int live;
  int * pointer;

  Value() : pointer(new int(7))
  {
    ++live;
  }

  Value(const Value & other) : pointer(new int(*other.pointer))
  {
    ++live;
  }

  ~Value()
  {
    delete pointer;
    --live;
  }
};

int Value::live = 0;

int consume(Value value)
{
  return *value.pointer;
}

int main()
{
  Value source;
  const int result = consume(source);
  return result == 7 && *source.pointer == 7 && Value::live == 1 ? 0 : 1;
}

