// A nested logical expression evaluated as the temporary-owning RHS of an
// outer short-circuit condition still needs value-result storage.
int destroyed = 0;

struct Probe
{
  ~Probe() noexcept { ++destroyed; }
};

bool use(const Probe&, bool value) noexcept
{
  return value;
}

int main()
{
  bool gate = true;
  if(gate && (use(Probe(), true) && true))
    ++destroyed;
  return 0;
}

// Nested logical lowering destroys only temporaries from evaluated arms,
// exactly once, before entering the selected statement arm.
int destroyed = 0;

struct Probe
{
  ~Probe() noexcept { ++destroyed; }
};

bool use(const Probe&, bool value) noexcept
{
  return value;
}

int main()
{
  if(use(Probe(), true) || (use(Probe(), true) && true))
  {
    if(destroyed != 1)
      return 1;
  }

  destroyed = 0;
  if(use(Probe(), false) || (use(Probe(), true) && true))
    return destroyed == 2 ? 0 : 2;
  return 3;
}

int destructions;

struct Step
{
  Step() {}
  ~Step() { ++destructions; }
};

struct Iterator
{
  int* current;

  int& operator*() const { return *current; }
  Step operator++() { ++current; return Step(); }
  bool operator!=(const Iterator& other) const
  {
    return current != other.current;
  }
};

struct Range
{
  int values[2];
  Iterator begin() { return Iterator{values}; }
  Iterator end() { return Iterator{values + 2}; }
};

int main()
{
  Range range = {{4, 5}};
  int sum = 0;
  for (int value : range)
    sum = sum + value;
  return destructions == 2 && sum == 9 ? 0 : 1;
}

